// 税込金額を計算して返す（端数切り捨て）
function calcTax(price, rate) {
  return Math.floor(price * (1 + rate));
}

// 日付を指定書式の文字列にして返す
function formatDate(date, fmt) {
  const d = new Date(date); const p = (n) => String(n).padStart(2, '0'); return fmt.replace('YYYY', d.getFullYear()).replace('MM', p(d.getMonth() + 1)).replace('DD', p(d.getDate()));
}

// 郵便番号から住所を非同期で取得して返す
async function lookupAddress(zip) {
  const res = await vja.fetch('https://zipcloud.ibsnet.co.jp/api/search?zipcode=' + zip); const json = await res.json(); return json.results ? json.results[0].address1 : null;
}

// メールアドレスの形式が正しいか判定する
function isValidEmail(text) {
  return /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(text);
}

// 全角英数字を半角に変換して返す
function toHalfWidth(text) {
  return text.replace(/[Ａ-Ｚａ-ｚ０-９]/g, (c) => String.fromCharCode(c.charCodeAt(0) - 0xFEE0));
}

// 誕生日から現在の年齢を計算して返す
function calcAge(birthday) {
  const b = new Date(birthday); const n = new Date(); let a = n.getFullYear() - b.getFullYear(); if (n < new Date(n.getFullYear(), b.getMonth(), b.getDate())) a--; return a;
}

// 通貨コードから対円の為替レートを非同期で取得して返す
async function fetchExchangeRate(currency) {
  const res = await vja.fetch('https://example.com/rate/' + currency); const json = await res.json(); return json.rate;
}

// カード番号の下4桁以外を * で伏せて返す
function maskCardNumber(cardNo) {
  return cardNo.slice(-4).padStart(cardNo.length, '*');
}

// 通知を非同期で送信する
async function sendNotification(to, message) {
  const res = await vja.fetch('https://example.com/notify', { method: 'POST', body: JSON.stringify({ to, message }) }); return res.ok;
}

// 数値を指定の小数桁で四捨五入して返す
function roundTo(value, digits) {
  const f = Math.pow(10, digits); return Math.round(value * f) / f;
}
